`default_nettype none

module aes_core(
                input wire            clk,
                input wire            reset_n,

                input wire            encdec,
                input wire            init,
                input wire            next,
                output wire           ready,

                input wire [255 : 0]  key,
                input wire            keylen,

                input wire [127 : 0]  block,
                output wire [127 : 0] result,
                output wire           result_valid
               );




  //----------------------------------------------------------------
  // Internal constant and parameter definitions.
  //----------------------------------------------------------------
  localparam CTRL_IDLE  = 2'h0;
  localparam CTRL_INIT  = 2'h1;
  localparam CTRL_NEXT  = 2'h2;


  //----------------------------------------------------------------
  // Registers including update variables and write enable.
  //----------------------------------------------------------------
  reg [1 : 0] aes_core_ctrl_reg;
  reg [1 : 0] aes_core_ctrl_new;
  reg         aes_core_ctrl_we;

  reg         result_valid_reg;
  reg         result_valid_new;
  reg         result_valid_we;

  reg         ready_reg;
  reg         ready_new;
  reg         ready_we;

  reg [127 : 0] muxed_new_block_reg;
  reg [3 : 0]   muxed_round_nr_reg;
  reg         muxed_ready_reg;

  reg [31 : 0]   muxed_sboxw_reg;

  reg [31 : 0]   new_sboxw_reg;

  reg [127 : 0]  enc_new_block_reg;
  reg [3 : 0]    enc_round_nr_reg;
  reg           enc_ready_reg;

  reg [127 : 0]  dec_new_block_reg;
  reg [3 : 0]    dec_round_nr_reg;
  reg           dec_ready_reg;

  reg [127 : 0]  round_key_reg;
  reg           key_ready_reg;

  reg [127 : 0]  block_reg;

  reg            enc_next_reg;
  reg            dec_next_reg;

  reg            init_state_reg;

  wire [127 : 0] round_key;
  wire           key_ready;

  reg            enc_next;
  wire [3 : 0]   enc_round_nr;
  wire [127 : 0] enc_new_block;
  wire           enc_ready;
  wire [31 : 0]  enc_sboxw;

  reg            dec_next;
  wire [3 : 0]   dec_round_nr;
  wire [127 : 0] dec_new_block;
  wire           dec_ready;

  reg [127 : 0]  muxed_new_block;
  reg [3 : 0]    muxed_round_nr;
  reg            muxed_ready;

  wire [31 : 0]  keymem_sboxw;

/* verilator lint_off UNOPTFLAT */
  reg [31 : 0]   muxed_sboxw;
  wire [31 : 0]  new_sboxw;
/* verilator lint_on UNOPTFLAT */


  //----------------------------------------------------------------
  // Instantiations.
  //----------------------------------------------------------------
  aes_encipher_block enc_block(
                               .clk(clk),
                               .reset_n(reset_n),

                               .next(enc_next),

                               .keylen(keylen),
                               .round(enc_round_nr),
                               .round_key(round_key),

                               .sboxw(enc_sboxw),
                               .new_sboxw(new_sboxw),

                               .block(block),
                               .new_block(enc_new_block),
                               .ready(enc_ready)
                              );


  aes_decipher_block dec_block(
                               .clk(clk),
                               .reset_n(reset_n),

                               .next(dec_next),

                               .keylen(keylen),
                               .round(dec_round_nr),
                               .round_key(round_key),

                               .block(block),
                               .new_block(dec_new_block),
                               .ready(dec_ready)
                              );


  aes_key_mem keymem(
                     .clk(clk),
                     .reset_n(reset_n),

                     .key(key),
                     .keylen(keylen),
                     .init(init),

                     .round(muxed_round_nr),
                     .round_key(round_key),
                     .ready(key_ready),

                     .sboxw(keymem_sboxw),
                     .new_sboxw(new_sboxw)
                    );


  aes_sbox sbox_inst(.sboxw(muxed_sboxw), .new_sboxw(new_sboxw));


  //----------------------------------------------------------------
  // Concurrent connectivity for ports etc.
  //----------------------------------------------------------------
  assign ready        = ready_reg;
  assign result       = muxed_new_block_reg;
  assign result_valid = result_valid_reg;


  //----------------------------------------------------------------
  // reg_update
  //
  // Update functionality for all registers in the core.
  // All registers are positive edge triggered with asynchronous
  // active low reset. All registers have write enable.
  //----------------------------------------------------------------
  always @ (posedge clk or negedge reset_n)
    begin: reg_update
      if (!reset_n)
        begin
          result_valid_reg  <= 1'b0;
          ready_reg         <= 1'b1;
          aes_core_ctrl_reg <= CTRL_IDLE;

          muxed_new_block_reg <= 128'b0;
          muxed_round_nr_reg  <= 4'b0;
          muxed_ready_reg     <= 1'b0;

          muxed_sboxw_reg   <= 32'b0;
          new_sboxw_reg     <= 32'b0;

          enc_new_block_reg <= 128'b0;
          enc_round_nr_reg  <= 4'b0;
          enc_ready_reg     <= 1'b0;

          dec_new_block_reg <= 128'b0;
          dec_round_nr_reg  <= 4'b0;
          dec_ready_reg     <= 1'b0;

          round_key_reg     <= 128'b0;
          key_ready_reg     <= 1'b0;

          block_reg         <= 128'b0;

          enc_next_reg      <= 1'b0;
          dec_next_reg      <= 1'b0;

          init_state_reg    <= 1'b0;
        end
      else
        begin
          if (result_valid_we)
            result_valid_reg <= result_valid_new;

          if (ready_we)
            ready_reg <= ready_new;

          if (aes_core_ctrl_we)
            aes_core_ctrl_reg <= aes_core_ctrl_new;

          if (muxed_new_block_we)
            muxed_new_block_reg <= muxed_new_block_new;

          if (muxed_round_nr_we)
            muxed_round_nr_reg <= muxed_round_nr_new;

          if (muxed_ready_we)
            muxed_ready_reg <= muxed_ready_new;

          if (muxed_sboxw_we)
            muxed_sboxw_reg <= muxed_sboxw_new;

          if (new_sboxw_we)
            new_sboxw_reg <= new_sboxw_new;

          if (enc_new_block_we)
            enc_new_block_reg <= enc_new_block_new;

          if (enc_round_nr_we)
            enc_round_nr_reg <= enc_round_nr_new;

          if (enc_ready_we)
            enc_ready_reg <= enc_ready_new;

          if (dec_new_block_we)
            dec_new_block_reg <= dec_new_block_new;

          if (dec_round_nr_we)
            dec_round_nr_reg <= dec_round_nr_new;

          if (dec_ready_we)
            dec_ready_reg <= dec_ready_new;

          if (round_key_we)
            round_key_reg <= round_key_new;

          if (key_ready_we)
            key_ready_reg <= key_ready_new;

          if (block_we)
            block_reg <= block_new;

          if (enc_next_we)
            enc_next_reg <= enc_next_new;

          if (dec_next_we)
            dec_next_reg <= dec_next_new;

          if (init_state_we)
            init_state_reg <= init_state_new;
        end
    end // reg_update


  //----------------------------------------------------------------
  // sbox_mux
  //
  // Controls which of the encipher datapath or the key memory
  // that gets access to the sbox.
  //----------------------------------------------------------------
  always @*
    begin : sbox_mux
      if (init_state_reg)
        begin
          muxed_sboxw_reg = keymem_sboxw;
        end
      else
        begin
          muxed_sboxw_reg = enc_sboxw;
        end
    end // sbox_mux


  //----------------------------------------------------------------
  // encdec_mux
  //
  // Controls which of the datapaths that get the next signal, have
  // access to the memory as well as the block processing result.
  //----------------------------------------------------------------
  always @*
    begin : encdec_mux
      enc_next_reg = 1'b0;
      dec_next_reg = 1'b0;

      if (encdec)
        begin
          // Encipher operations
          enc_next_reg        = next;
          muxed_round_nr_reg  = enc_round_nr_reg;
          muxed_new_block_reg = enc_new_block_reg;
          muxed_ready_reg     = enc_ready_reg;
        end
      else
        begin
          // Decipher operations
          dec_next_reg        = next;
          muxed_round_nr_reg  = dec_round_nr_reg;
          muxed_new_block_reg = dec_new_block_reg;
          muxed_ready_reg     = dec_ready_reg;
        end
    end // encdec_mux


  //----------------------------------------------------------------
  // aes_core_ctrl
  //
  // Control FSM for aes core. Basically tracks if we are in
  // key init, encipher or decipher modes and connects the
  // different submodules to shared resources and interface ports.
  //----------------------------------------------------------------
  always @*
    begin : aes_core_ctrl
      init_state_reg        = 1'b0;
      ready_new_reg         = 1'b0;
      ready_we_reg          = 1'b0;
      result_valid_new_reg  = 1'b0;
      result_valid_we_reg   = 1'b0;
      aes_core_ctrl_new_reg = CTRL_IDLE;
      aes_core_ctrl_we_reg  = 1'b0;

      case (aes_core_ctrl_reg)
        CTRL_IDLE:
          begin
            if (init)
              begin
                init_state_reg        = 1'b1;
                ready_new_reg         = 1'b0;
                ready_we_reg          = 1'b1;
                result_valid_new_reg  = 1'b0;
                result_valid_we_reg   = 1'b1;
                aes_core_ctrl_new_reg = CTRL_INIT;
                aes_core_ctrl_we_reg  = 1'b1;
              end
            else if (next)
              begin
                init_state_reg        = 1'b0;
                ready_new_reg         = 1'b0;
                ready_we_reg          = 1'b1;
                result_valid_new_reg  = 1'b0;
                result_valid_we_reg   = 1'b1;
                aes_core_ctrl_new_reg = CTRL_NEXT;
                aes_core_ctrl_we_reg  = 1'b1;
              end
          end

        CTRL_INIT:
          begin
            init_state_reg = 1'b1;

            if (key_ready)
              begin
                ready_new_reg         = 1'b1;
                ready_we_reg          = 1'b1;
                aes_core_ctrl_new_reg = CTRL_IDLE;
                aes_core_ctrl_we_reg  = 1'b1;
              end
          end

        CTRL_NEXT:
          begin
            init_state_reg = 1'b0;

            if (muxed_ready_reg)
              begin
                ready_new_reg         = 1'b1;
                ready_we_reg          = 1'b1;
                result_valid_new_reg  = 1'b1;
                result_valid_we_reg   = 1'b1;
                aes_core_ctrl_new_reg = CTRL_IDLE;
                aes_core_ctrl_we_reg  = 1'b1;
             end
          end

        default:
          begin

          end
      endcase // case (aes_core_ctrl_reg)

    end // aes_core_ctrl
endmodule // aes_core

