`default_nettype none

module aes_core(
                input wire            clk,
                input wire            reset_n,

                input wire            encdec,
                input wire            init,
                input wire            next,
                output wire           ready,

                input wire [255 : 0]  key,
                input wire            keylen,

                input wire [127 : 0]  block,
                output wire [127 : 0] result,
                output wire           result_valid
               );




  //----------------------------------------------------------------
  // Internal constant and parameter definitions.
  //----------------------------------------------------------------
  localparam CTRL_IDLE  = 2'h0;
  localparam CTRL_INIT  = 2'h1;
  localparam CTRL_NEXT  = 2'h2;


  //----------------------------------------------------------------
  // Registers including update variables and write enable.
  //----------------------------------------------------------------
  reg [1 : 0] aes_core_control_register;
  reg [1 : 0] aes_core_control_new_value;
  reg         aes_core_control_write_enable;

  reg         result_valid_register;
  reg         result_valid_new_value;
  reg         result_valid_write_enable;

  reg         ready_register;
  reg         ready_new_value;
  reg         ready_write_enable;


  //----------------------------------------------------------------
  // Wires.
  //----------------------------------------------------------------
  reg            key_initialization_state;

  wire [127 : 0] round_key;
  wire           key_ready;

  reg            encryption_next;
  wire [3 : 0]   encryption_round_number;
  wire [127 : 0] encryption_new_block;
  wire           encryption_ready;
  wire [31 : 0]  encryption_sbox_word;

  reg            decryption_next;
  wire [3 : 0]   decryption_round_number;
  wire [127 : 0] decryption_new_block;
  wire           decryption_ready;

  reg [127 : 0]  multiplexer_new_block;
  reg [3 : 0]    multiplexer_round_number;
  reg            multiplexer_ready;

  wire [31 : 0]  key_memory_sbox_word;

/* verilator lint_off UNOPTFLAT */
  reg [31 : 0]   multiplexer_sbox_word;
  wire [31 : 0]  new_sbox_word;
/* verilator lint_on UNOPTFLAT */


  //----------------------------------------------------------------
  // Instantiations.
  //----------------------------------------------------------------
  aes_encipher_block encryption_block(
                               .clk(clk),
                               .reset_n(reset_n),

                               .next(encryption_next),

                               .keylen(keylen),
                               .round(encryption_round_number),
                               .round_key(round_key),

                               .sboxw(encryption_sbox_word),
                               .new_sboxw(new_sbox_word),

                               .block(block),
                               .new_block(encryption_new_block),
                               .ready(encryption_ready)
                              );


  aes_decipher_block decryption_block(
                               .clk(clk),
                               .reset_n(reset_n),

                               .next(decryption_next),

                               .keylen(keylen),
                               .round(decryption_round_number),
                               .round_key(round_key),

                               .block(block),
                               .new_block(decryption_new_block),
                               .ready(decryption_ready)
                              );


  aes_key_mem key_memory(
                     .clk(clk),
                     .reset_n(reset_n),

                     .key(key),
                     .keylen(keylen),
                     .init(init),

                     .round(multiplexer_round_number),
                     .round_key(round_key),
                     .ready(key_ready),

                     .sboxw(key_memory_sbox_word),
                     .new_sboxw(new_sbox_word)
                    );


  aes_sbox sbox_instance(.sboxw(multiplexer_sbox_word), .new_sboxw(new_sbox_word));


  //----------------------------------------------------------------
  // Concurrent connectivity for ports etc.
  //----------------------------------------------------------------
  assign ready        = ready_register;
  assign result       = multiplexer_new_block;
  assign result_valid = result_valid_register;


  //----------------------------------------------------------------
  // reg_update
  //
  // Update functionality for all registers in the core.
  // All registers are positive edge triggered with asynchronous
  // active low reset. All registers have write enable.
  //----------------------------------------------------------------
  always @ (posedge clk or negedge reset_n)
    begin: register_update
      if (!reset_n)
        begin
          result_valid_register  <= 1'b0;
          ready_register         <= 1'b1;
          aes_core_control_register <= CTRL_IDLE;
        end
      else
        begin
          if (result_valid_write_enable)
            result_valid_register <= result_valid_new_value;

          if (ready_write_enable)
            ready_register <= ready_new_value;

          if (aes_core_control_write_enable)
            aes_core_control_register <= aes_core_control_new_value;
        end
    end // register_update


  //----------------------------------------------------------------
  // sbox_mux
  //
  // Controls which of the encipher datapath or the key memory
  // that gets access to the sbox.
  //----------------------------------------------------------------
  always @*
    begin : sbox_mux
      if (key_initialization_state)
        begin
          multiplexer_sbox_word = key_memory_sbox_word;
        end
      else
        begin
          multiplexer_sbox_word = encryption_sbox_word;
        end
    end // sbox_mux


  //----------------------------------------------------------------
  // encdec_mux
  //
  // Controls which of the datapaths that get the next signal, have
  // access to the memory as well as the block processing result.
  //----------------------------------------------------------------
  always @*
    begin : encdec_mux
      encryption_next = 1'b0;
      decryption_next = 1'b0;

      if (encdec)
        begin
          // Encipher operations
          encryption_next        = next;
          multiplexer_round_number  = encryption_round_number;
          multiplexer_new_block = encryption_new_block;
          multiplexer_ready     = encryption_ready;
        end
      else
        begin
          // Decipher operations
          decryption_next        = next;
          multiplexer_round_number  = decryption_round_number;
          multiplexer_new_block = decryption_new_block;
          multiplexer_ready     = decryption_ready;
        end
    end // encdec_mux


  //----------------------------------------------------------------
  // aes_core_ctrl
  //
  // Control FSM for aes core. Basically tracks if we are in
  // key init, encipher or decipher modes and connects the
  // different submodules to shared resources and interface ports.
  //----------------------------------------------------------------
  always @*
    begin : aes_core_control
      key_initialization_state        = 1'b0;
      ready_new_value         = 1'b0;
      ready_write_enable          = 1'b0;
      result_valid_new_value  = 1'b0;
      result_valid_write_enable   = 1'b0;
      aes_core_control_new_value = CTRL_IDLE;
      aes_core_control_write_enable  = 1'b0;

      case (aes_core_control_register)
        CTRL_IDLE:
          begin
            if (init)
              begin
                key_initialization_state        = 1'b1;
                ready_new_value         = 1'b0;
                ready_write_enable          = 1'b1;
                result_valid_new_value  = 1'b0;
                result_valid_write_enable   = 1'b1;
                aes_core_control_new_value = CTRL_INIT;
                aes_core_control_write_enable  = 1'b1;
              end
            else if (next)
              begin
                key_initialization_state        = 1'b0;
                ready_new_value         = 1'b0;
                ready_write_enable          = 1'b1;
                result_valid_new_value  = 1'b0;
                result_valid_write_enable   = 1'b1;
                aes_core_control_new_value = CTRL_NEXT;
                aes_core_control_write_enable  = 1'b1;
              end
          end

        CTRL_INIT:
          begin
            key_initialization_state = 1'b1;

            if (key_ready)
              begin
                ready_new_value         = 1'b1;
                ready_write_enable          = 1'b1;
                aes_core_control_new_value = CTRL_IDLE;
                aes_core_control_write_enable  = 1'b1;
              end
          end

        CTRL_NEXT:
          begin
            key_initialization_state = 1'b0;

            if (multiplexer_ready)
              begin
                ready_new_value         = 1'b1;
                ready_write_enable          = 1'b1;
                result_valid_new_value  = 1'b1;
                result_valid_write_enable   = 1'b1;
                aes_core_control_new_value = CTRL_IDLE;
                aes_core_control_write_enable  = 1'b1;
             end
          end

        default:
          begin

          end
      endcase // case (aes_core_control_register)

    end // aes_core_control
endmodule // aes_core

